package com.bank.spark.model;

// Describes how many partitions each stage runs with.
public class StagePlan {
    private final int upstreamParallelism; // tasks running the expensive work
    private final int outputPartitions;    // final file count

    public StagePlan(int upstreamParallelism, int outputPartitions) {
        this.upstreamParallelism = upstreamParallelism;
        this.outputPartitions = outputPartitions;
    }

    public int getUpstreamParallelism() { return upstreamParallelism; }
    public int getOutputPartitions() { return outputPartitions; }
}
