package com.bank.spark.service;

import com.bank.spark.model.StagePlan;

// Plans how coalesce affects upstream parallelism, with and without shuffle.
public class CoalescePlanner {

    // Plain coalesce(n): no shuffle boundary, so n is pushed up the chain.
    public StagePlan planPlainCoalesce(int sourcePartitions, int n) {
        // Upstream collapses to n because there is no exchange to decouple it.
        return new StagePlan(n, n);
    }

    // coalesce(n, shuffle=true): a shuffle boundary is inserted.
    public StagePlan planCoalesceWithShuffle(int sourcePartitions, int n) {
        // Upstream keeps its full parallelism; only the output stage uses n.
        return new StagePlan(sourcePartitions, n);
    }

    // repartition(n) is implemented as coalesce(n, shuffle=true) — same plan.
    public StagePlan planRepartition(int sourcePartitions, int n) {
        return planCoalesceWithShuffle(sourcePartitions, n);
    }
}
