package com.bank.spark;

import com.bank.spark.model.StagePlan;
import com.bank.spark.service.CoalescePlanner;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CoalesceDemo {

    private static final Logger log = Logger.getLogger(CoalesceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CoalescePlanner planner = new CoalescePlanner();
        int source = 200; // the day's trade partitions
        int target = 4;   // we want 4 output files

        StagePlan plain = planner.planPlainCoalesce(source, target);
        log.warning(() -> "coalesce(4): upstream parallelism collapses to "
                + plain.getUpstreamParallelism() + " tasks — expensive work runs in only 4 tasks!");

        StagePlan withShuffle = planner.planCoalesceWithShuffle(source, target);
        log.info(() -> "coalesce(4, shuffle=true): upstream keeps "
                + withShuffle.getUpstreamParallelism() + " tasks, output = "
                + withShuffle.getOutputPartitions() + " files");

        StagePlan repart = planner.planRepartition(source, target);
        boolean equivalent = repart.getUpstreamParallelism() == withShuffle.getUpstreamParallelism()
                && repart.getOutputPartitions() == withShuffle.getOutputPartitions();
        log.info("repartition(4) plan equals coalesce(4, shuffle=true) plan? " + equivalent);

        if (equivalent) {
            log.info("Proven: repartition(n) IS coalesce(n, shuffle=true).");
        } else {
            log.severe("Unexpected: plans differ.");
        }
    }
}

